<script setup lang="ts">
import {axisBounds,tankAxes,trendNames} from './trendSettings';
import {calendarRange,type CalendarPeriod} from './calendarRange';
import {previewPrint} from './printPreview';
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {init,use,type EChartsCoreOption,type EChartsType} from 'echarts/core';
import {LineChart} from 'echarts/charts';
import {GridComponent,TooltipComponent,LegendComponent,DataZoomComponent} from 'echarts/components';
import {CanvasRenderer} from 'echarts/renderers';
import {api,can,type Configuration,type TrendQuantity,type TrendResult,type TrendPoint,type TrendAxisSetting} from './api';
import {converted,unit,qualityNames,type Quantity} from './units';
use([LineChart,GridComponent,TooltipComponent,LegendComponent,DataZoomComponent,CanvasRenderer]);
const props=defineProps<{licensed:boolean;config:Configuration;admin:boolean;dirty:boolean;focusTank?:string}>(),emit=defineEmits<{updated:[Configuration]}>();
const names=trendNames;
const palette=['#318c9b','#b27852','#75934b','#865cb1','#be626c'];
const firstTank=props.config.tanks.find(t=>t.id===props.focusTank)||props.config.tanks.find(t=>!t.hidden);
const currentTankId=ref(firstTank?.id||'');
const currentTank=computed(()=>props.config.tanks.find(t=>t.id===currentTankId.value));
const axes=ref(tankAxes(firstTank));
const selected=ref<{tankId:string;quantity:TrendQuantity;color:string}[]>((firstTank?.trends.quantities||[]).map((quantity,i)=>({tankId:firstTank!.id,quantity,color:firstTank!.trends.colors[i]||palette[i]!})));
const mode=ref('realtime'),start=ref(localInput(Date.now()-1800000)),end=ref(localInput(Date.now()+60000)),data=ref<TrendResult|null>(null),error=ref(''),message=ref(''),busy=ref(false),paused=ref(false),canvas=ref<HTMLElement|null>(null);
let chart:EChartsType|undefined,timer:ReturnType<typeof setInterval>|undefined,observer:ResizeObserver|undefined,generation=0,queued=false,queuedReset=false,disposed=false;
const activeQuantities=computed(()=>[...new Set(selected.value.map(s=>s.quantity))]);
function chooseTank(){const t=currentTank.value;if(!t)return;selected.value=t.trends.quantities.map((quantity,i)=>({tankId:t.id,quantity,color:t.trends.colors[i]||palette[i]!}));axes.value=tankAxes(t);message.value='已载入该罐保存的曲线和纵轴设置。';void load(true)}
function displayedAxis(quantity:TrendQuantity,key:'minimumSpan'|'minimum'|'maximum'){const n=axes.value[quantity][key];return n===null?'':value(n,quantity)}
function setAxis(quantity:TrendQuantity,key:'minimumSpan'|'minimum'|'maximum',event:Event){const text=(event.target as HTMLInputElement).value;const n=text===''?null:Number(text)/value(1,quantity);if(key==='minimumSpan')axes.value[quantity].minimumSpan=n??0;else axes.value[quantity][key]=n;draw()}
const axisErrors=computed(()=>activeQuantities.value.filter(q=>{const a=axes.value[q];return !Number.isFinite(a.minimumSpan)||a.minimumSpan<0||a.mode==='Fixed'&&(a.minimum===null||a.maximum===null||a.maximum<=a.minimum)}).map(q=>names[q]+'：跨度须非负，固定上限须大于下限'));
const outsideFixed=computed(()=>activeQuantities.value.flatMap(q=>{const a=axes.value[q];if(a.mode!=='Fixed'||a.minimum===null||a.maximum===null||a.maximum<=a.minimum)return [];const points=data.value?.series.filter(s=>s.selection.quantity===q).flatMap(s=>s.points.filter(p=>p.quality==='Good'&&p.value!==null).map(p=>p.value!))||[];const outside=points.filter(v=>v<a.minimum!||v>a.maximum!);return outside.length?[names[q]+'有'+outside.length+'个点超出固定范围；实际最小/最大 '+value(Math.min(...points),q).toLocaleString()+' / '+value(Math.max(...points),q).toLocaleString()+' '+unitName(q)+'，请扩大范围查看']:[]}));
function quickRange(period:CalendarPeriod){const range=calendarRange(period);end.value=localInput(range.end.getTime());start.value=localInput(range.start.getTime());void load(true,{startUtcMs:range.start.getTime(),endUtcMs:range.end.getTime()})}
function quantityBounds(q:TrendQuantity,snapshot:TrendResult){const values=snapshot.series.filter(s=>s.selection.quantity===q).flatMap(s=>s.points.filter(p=>p.quality==='Good'&&p.value!==null).map(p=>value(p.value!,q)));return axisBounds(axes.value[q],values,value(1,q))}
function localInput(ms:number){const d=new Date(ms);return new Date(ms-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function q(quantity:TrendQuantity):Quantity|null{return ({Level:'level',InstantTemperature:'temperature',AverageTemperature:'temperature',Density:'density',CurrentVolume:'volume',NetVolume:'volume',Mass:'mass'} as Partial<Record<TrendQuantity,Quantity>>)[quantity]||null}
function unitName(quantity:TrendQuantity){const key=q(quantity);return key?unit(key,props.config.display):'kPa'}
function value(v:number,quantity:TrendQuantity){const key=q(quantity);return key?converted(v,key,props.config.display):v}
function label(s:{tankId:string;quantity:TrendQuantity}){return (props.config.tanks.find(t=>t.id===s.tankId)?.code||'储罐')+' · '+names[s.quantity]}
function format(p:TrendPoint|undefined,quantity:TrendQuantity){return p?.value!==null&&p?.value!==undefined&&p.quality==='Good'?value(p.value,quantity).toLocaleString('zh-CN',{maximumFractionDigits:6})+' '+unitName(quantity):'—'+(p?'（'+(qualityNames[p.quality]||'无有效数据')+'）':'（此时刻无样本）')}
const hasData=computed(()=>data.value?.series.some(s=>s.points.some(p=>p.value!==null)));
async function load(reset=false,range?:{startUtcMs:number;endUtcMs:number}){if(!selected.value.length||disposed||mode.value==='history'&&!props.licensed)return;if(busy.value){queued=true;queuedReset ||=reset;return;}busy.value=true;error.value='';const token=++generation;try{const series=selected.value.map(({tankId,quantity})=>({tankId,quantity}));const input={startUtcMs:mode.value==='realtime'?0:(range?.startUtcMs??new Date(start.value).getTime()),endUtcMs:mode.value==='realtime'?1:(range?.endUtcMs??new Date(end.value).getTime()),series,maximumPoints:2000};const result=await api<TrendResult>('/api/trends/'+mode.value,'POST',input);if(token!==generation||mode.value==='history'&&!props.licensed)return;data.value=result;await nextTick();draw(reset)}catch(e){error.value=String(e)}finally{busy.value=false;if(queued&&!disposed){const resetNext=queuedReset;queued=false;queuedReset=false;void load(resetNext)}}}
function escape(text:string){return text.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!))}
function draw(reset=false){if(!canvas.value||!data.value)return;chart??=init(canvas.value);const snapshot=data.value,units=[...new Set(snapshot.series.map(s=>s.selection.quantity))];
 const lookup=snapshot.series.map(s=>new Map(s.points.map(p=>[p.atUtcMs,p])));
 const zoom=reset?undefined:(chart.getOption() as {dataZoom?:{start?:number;end?:number}[]}).dataZoom?.[0];
 const option:EChartsCoreOption={animation:false,color:selected.value.map(s=>s.color),legend:{type:'scroll',top:8,textStyle:{color:'#52717e'}},grid:{top:88,bottom:84,left:units.length>4?160:units.length>2?110:70,right:units.length>3?120:units.length>1?65:32},xAxis:{type:'time',min:snapshot.startUtcMs,max:snapshot.endUtcMs,axisLabel:{formatter:(v:number)=>new Date(v).toLocaleTimeString('zh-CN',{hour12:false})},axisPointer:{show:true,snap:true}},yAxis:units.map((u,i)=>({type:'value',name:names[u]+'\n'+unitName(u),nameTextStyle:{fontSize:11,lineHeight:15},scale:true,...quantityBounds(u,snapshot),position:i%2?'right':'left',offset:Math.floor(i/2)*55,splitLine:{show:i===0},axisLabel:{formatter:(v:number)=>v.toLocaleString('zh-CN',{maximumFractionDigits:4})}})),dataZoom:[{type:'slider',bottom:20,start:zoom?.start??0,end:zoom?.end??100},{type:'inside',start:zoom?.start??0,end:zoom?.end??100}],tooltip:{trigger:'axis',confine:true,axisPointer:{type:'cross'},formatter:(raw:unknown)=>{const parameters=raw as {value?:[number,number|null]}[];const at=parameters.find(p=>p.value?.[0]!==undefined)?.value?.[0];if(at===undefined)return '';return '<b>'+escape(new Date(at).toLocaleString('zh-CN',{hour12:false}))+'</b><br>'+snapshot.series.map((s,i)=>escape(label(s.selection))+'：'+escape(format(lookup[i]!.get(at),s.selection.quantity))).join('<br>')}},series:snapshot.series.map((s,i)=>({id:s.selection.tankId+':'+s.selection.quantity,name:label(s.selection),type:'line',yAxisIndex:units.indexOf(s.selection.quantity),showSymbol:s.points.length<150,symbolSize:4,smooth:false,connectNulls:false,lineStyle:{width:1.6,color:selected.value[i]?.color||palette[i]},itemStyle:{color:selected.value[i]?.color||palette[i]},data:s.points.map(p=>[p.atUtcMs,p.quality==='Good'&&p.value!==null?value(p.value,s.selection.quantity):null])}))};chart.setOption(option,{notMerge:true});
}
function add(){if(selected.value.length>=5||!currentTank.value)return;const used=new Set(selected.value.filter(s=>s.tankId===currentTankId.value).map(s=>s.quantity));const quantity=(Object.keys(names) as TrendQuantity[]).find(q=>!used.has(q));if(!quantity)return;selected.value.push({tankId:currentTankId.value,quantity,color:palette[selected.value.length]!});void load(true)}
function remove(i:number){selected.value.splice(i,1);if(selected.value.length)void load(true);else{data.value=null;chart?.clear()}}
async function savePreset(){if(props.dirty){error.value='请先保存或重新载入其他配置';return}if(axisErrors.value.length){error.value=axisErrors.value.join('；');return}if(!selected.value.length||!selected.value.every(s=>s.tankId===currentTankId.value)){error.value='共用设置需选择同一个罐的1～5个数据项';return}try{const cfg=JSON.parse(JSON.stringify(props.config)) as Configuration;const tank=cfg.tanks.find(t=>t.id===currentTankId.value)!;tank.trends={quantities:selected.value.map(s=>s.quantity),colors:selected.value.map(s=>s.color),axes:JSON.parse(JSON.stringify(axes.value))};cfg.channels=cfg.channels.map(({isGateway,physicalKey,...c})=>c);emit('updated',await api('/api/config','PUT',cfg));message.value='该罐曲线及各数据项纵轴设置已保存，所有用户共用。'}catch(e){error.value=String(e)}}
function exportRows(){if(!props.licensed||!can('DataExport')||!data.value)return;window.LocalWorkbook.download('曲线显示点',[{name:'实际采样点',rows:[['储罐 / 数据项','时间','数值','单位','质量','缺测标记'],...data.value.series.flatMap(s=>s.points.map(p=>[label(s.selection),new Date(p.atUtcMs).toLocaleString('zh-CN',{hour12:false}),p.value===null?'':value(p.value,s.selection.quantity),unitName(s.selection.quantity),qualityNames[p.quality],p.gapMarker?'缺测断线':'']))]}])}
function print(){if(!props.licensed||!can('DataExport')||!data.value)return;previewPrint({title:mode.value==='realtime'?'实时趋势 · 最近30分钟':'历史趋势',readPermission:mode.value==='history'?'HistoryRead':undefined,scope:['图形范围：'+new Date(data.value.startUtcMs).toLocaleString('zh-CN',{hour12:false})+' 至 '+new Date(data.value.endUtcMs).toLocaleString('zh-CN',{hour12:false})+'（结束不含）',data.value.timeBasis,...outsideFixed.value,'打印当前图形与曲线说明；缺测断线，不估算。'],image:chart?.getDataURL({type:'png',pixelRatio:2,backgroundColor:'#fff'}),imageTitle:'当前趋势图',sections:[{title:'曲线说明',headers:['曲线','单位','来源记录数','显示点数','有效值点数','是否抽稀'],rows:data.value.series.map(s=>[label(s.selection),unitName(s.selection.quantity),s.sourceRows,s.points.length,s.points.filter(p=>p.quality==='Good'&&p.value!==null&&!p.gapMarker).length,s.reduced?'是':'否'])}]})}
function image(){if(!props.licensed||!chart)return;const a=document.createElement('a');a.href=chart.getDataURL({type:'png',pixelRatio:2,backgroundColor:'#fff'});a.download='趋势曲线.png';a.click()}
watch(()=>props.licensed,allowed=>{if(!allowed&&mode.value==='history'){generation++;data.value=null;chart?.clear();mode.value='realtime';void load(true)}});
onMounted(async()=>{await load(true);observer=new ResizeObserver(()=>chart?.resize());if(canvas.value)observer.observe(canvas.value);timer=setInterval(()=>{if(mode.value==='realtime'&&!paused.value)void load()},2000)});onUnmounted(()=>{disposed=true;generation++;if(timer)clearInterval(timer);observer?.disconnect();chart?.dispose()});watch(()=>props.config.display,()=>draw(),{deep:true});
</script>
<template><div class="notice">最多5条曲线；每种数据项独立刻度，同一数据项跨罐对比共用刻度。切换当前储罐会载入其保存设置，新增曲线默认使用当前罐。鼠标提示只显示该时刻实际保存的采样值；缺测断线，不估算。实时曲线显示最近30分钟。</div><p v-if="error" role="alert" class="notice error-message">{{error}}</p><p v-if="message" role="status" class="notice success-message">{{message}}</p><section class="panel panel-body trend-query"><form @submit.prevent="load(true)"><div class="toolbar"><label class="config-field">当前储罐<select v-model="currentTankId" aria-label="趋势当前储罐" @change="chooseTank"><option v-for="t in config.tanks" :key="t.id" :value="t.id">{{t.code}} · {{t.name||t.medium}}</option></select></label><label class="config-field">数据范围<select v-model="mode" aria-label="曲线数据范围" @change="load(true)"><option value="realtime">实时 · 最近30分钟</option><option value="history" :disabled="!licensed||!can('HistoryRead')">历史归档数据</option></select></label><template v-if="mode==='history'"><label class="config-field">开始时间<input v-model="start" type="datetime-local" required aria-label="曲线开始时间"></label><label class="config-field">结束时间（不含）<input v-model="end" type="datetime-local" required aria-label="曲线结束时间"></label></template><template v-if="mode==='history'"><button v-for="[d,label] in [['day','当日'],['week','本周'],['month','本月']]" :key="d" type="button" class="button" :disabled="busy" @click="quickRange(d as CalendarPeriod)" :title="label==='当日'?'今日00:00至当前':label==='本周'?'本周星期一00:00至当前':'本月1日00:00至当前'">{{label}}</button></template><button class="button primary" :disabled="busy||!selected.length">查询 / 更新</button><button v-if="mode==='realtime'" type="button" class="button" @click="paused=!paused">{{paused?'继续更新':'暂停查看'}}</button></div></form><details class="trend-axis-settings" open><summary>各数据项纵轴设置</summary><div class="table-wrap"><table><thead><tr><th>数据项 / 单位</th><th>纵轴方式</th><th>最小跨度</th><th>固定下限</th><th>固定上限</th></tr></thead><tbody><tr v-for="q in activeQuantities" :key="q" :data-axis-quantity="q"><td>{{names[q]}} {{unitName(q)}}</td><td><select v-model="axes[q].mode" :aria-label="names[q]+'纵轴方式'" @change="draw()"><option value="Auto">自动（保留最小跨度）</option><option value="Fixed">固定上下限</option></select></td><td><input :value="displayedAxis(q,'minimumSpan')" :aria-label="names[q]+'最小跨度'" type="number" min="0" step="any" :disabled="axes[q].mode==='Fixed'" @input="setAxis(q,'minimumSpan',$event)"></td><td><input :value="displayedAxis(q,'minimum')" :aria-label="names[q]+'固定下限'" type="number" step="any" :disabled="axes[q].mode!=='Fixed'" @input="setAxis(q,'minimum',$event)"></td><td><input :value="displayedAxis(q,'maximum')" :aria-label="names[q]+'固定上限'" type="number" step="any" :disabled="axes[q].mode!=='Fixed'" @input="setAxis(q,'maximum',$event)"></td></tr></tbody></table></div><p class="help">刻度仅改变显示，原始值、极值及缺测状态保留。输入使用上方显示单位；保存后单罐实时趋势也采用该罐刻度。</p><p v-for="text in axisErrors" :key="text" class="error-message">{{text}}，暂按自动范围显示。</p></details><div v-for="(s,i) in selected" :key="i" class="trend-selection"><span>{{i+1}}</span><select v-model="s.tankId" :aria-label="'曲线'+(i+1)+'储罐'" @change="load(true)"><option v-for="t in config.tanks" :key="t.id" :value="t.id">{{t.code}}</option></select><select v-model="s.quantity" :aria-label="'曲线'+(i+1)+'数据项'" @change="load(true)"><option v-for="(label,key) in names" :key="key" :value="key">{{label}}</option></select><input v-model="s.color" type="color" :aria-label="'曲线'+(i+1)+'颜色'" @input="draw()"><button class="text-button" @click="remove(i)">移除</button></div><div class="toolbar"><button class="button" :disabled="selected.length>=5" @click="add">增加曲线</button><button v-if="admin" class="button" :disabled="!selected.length||busy" @click="savePreset">保存该罐共用曲线设置</button><span class="help">不同储罐可临时比较；共用设置按单罐保存。</span></div></section><section class="panel"><p v-for="text in outsideFixed" :key="text" class="notice error-message">{{text}}</p><div class="toolbar"><span>{{mode==='realtime'?'最近30分钟实时曲线':'历史趋势'}}{{paused&&mode==='realtime'?' · 已暂停':''}}</span><div><button class="button" :disabled="!licensed||!can('DataExport')||!data" :data-export-allowed="can('DataExport')" @click="can('DataExport')&&exportRows()">导出曲线显示点</button><button class="button" :disabled="!licensed||!can('DataExport')||!hasData" @click="image">保存曲线图片</button><button class="button" :disabled="!licensed||!can('DataExport')||!data||busy" @click="print">打印预览</button></div></div><div ref="canvas" class="trend-canvas" role="img" aria-label="实时与历史趋势曲线"></div><div v-if="!hasData" class="empty">当前范围暂无有效数值；需要先启动采集，历史曲线按已保存的归档数据显示。</div><div class="table-foot">{{data?.timeBasis}}<br><span v-for="s in data?.series" :key="s.selection.tankId+s.selection.quantity">{{label(s.selection)}}：{{s.sourceRows}}条来源记录，显示{{s.points.length}}点{{s.reduced?'（保留实际首尾与极值）':''}}。 </span></div></section></template>
